# region imports
from AlgorithmImports import *
import math
# endregion


class StrategyLot:
    """A private lot of shares owned by a single strategy slot.

    Each strategy only ever sells shares that it bought itself, so the lot
    quantity is tracked independently of the shared portfolio holding.
    """

    def __init__(self, algorithm, symbol, name):
        self.algorithm = algorithm
        self.symbol = symbol
        self.name = name
        self.shares = 0

    @property
    def is_open(self):
        return self.shares > 0

    @property
    def is_empty(self):
        return self.shares <= 0

    def buy(self, quantity):
        quantity = int(quantity)
        if quantity <= 0:
            return False
        self.algorithm.market_order(self.symbol, quantity)
        self.shares += quantity
        self.algorithm.log(f"{self.algorithm.time.date()} {self.name} BUY {quantity} {self.symbol.value}")
        return True

    def sell(self, quantity):
        quantity = int(min(quantity, self.shares))
        if quantity <= 0:
            return False
        # never try to sell more than the account actually holds
        held = int(self.algorithm.portfolio[self.symbol].quantity)
        quantity = int(min(quantity, max(held, 0)))
        if quantity <= 0:
            self.shares = 0
            return False
        self.algorithm.market_order(self.symbol, -quantity)
        self.shares -= quantity
        self.algorithm.log(f"{self.algorithm.time.date()} {self.name} SELL {quantity} {self.symbol.value}")
        return True

    def sell_half(self):
        if self.shares <= 0:
            return False
        quantity = 1 if self.shares == 1 else int(math.floor(self.shares / 2.0))
        return self.sell(quantity)

    def liquidate(self):
        return self.sell(self.shares)


class TwoSlotParallelTemplateAlgorithm(QCAlgorithm):
    """One template, two slots, no gate. Both slots run independently in parallel.

    Slot 1 - Strategy A (SPY): buy when close crosses above its moving average
             (40% of total portfolio value), sell the whole lot when close
             crosses below the moving average.
    Slot 2 - Strategy B (AAPL): buy $20,000 worth after 3 consecutive red days
             (only if $20,000 cash is available), sell the whole lot when the
             14-day RSI closes above 60.
    """

    TICKERS = ["SPY", "AAPL", "IBM", "BAC", "AIG"]

    SMA_PERIOD = 50            # moving average length used by Strategy A
    RSI_PERIOD = 14
    RSI_SELL_LEVEL = 60.0
    RED_DAYS_REQUIRED = 3
    A_ALLOCATION = 0.40
    B_CASH_PER_TRADE = 20000.0

    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1000000)

        self.symbols = {}
        for ticker in self.TICKERS:
            self.symbols[ticker] = self.add_equity(ticker, Resolution.DAILY).symbol

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        # Indicators (auto-updated by the daily data feed).
        self.spy_sma = self.sma(self.spy, self.SMA_PERIOD, Resolution.DAILY)
        self.aapl_rsi = self.rsi(self.aapl, self.RSI_PERIOD, MovingAverageType.WILDERS, Resolution.DAILY)

        # Private lots, one per slot.
        self.lot_a = StrategyLot(self, self.spy, "StrategyA")
        self.lot_b = StrategyLot(self, self.aapl, "StrategyB")

        # Market state maintained continuously from data.
        self.prev_close = {ticker: None for ticker in self.TICKERS}
        self.prev_spy_sma = None
        self.aapl_red_streak = 0

        self.set_warm_up(self.SMA_PERIOD + self.RSI_PERIOD + 20, Resolution.DAILY)

    # ------------------------------------------------------------------ #
    # helpers
    # ------------------------------------------------------------------ #
    @staticmethod
    def _crosses_above(prev_x, prev_y, x, y):
        """Yesterday X <= Y and today X > Y."""
        if prev_x is None or prev_y is None or x is None or y is None:
            return False
        return prev_x <= prev_y and x > y

    @staticmethod
    def _crosses_below(prev_x, prev_y, x, y):
        """Yesterday X >= Y and today X < Y."""
        if prev_x is None or prev_y is None or x is None or y is None:
            return False
        return prev_x >= prev_y and x < y

    def _collect_bars(self, data):
        bars = {}
        for ticker, symbol in self.symbols.items():
            if data.bars.contains_key(symbol):
                bar = data.bars[symbol]
                if bar is not None and bar.close > 0:
                    bars[ticker] = bar
        return bars

    def _ready_to_trade(self):
        if self.is_warming_up:
            return False
        if not self.spy_sma.is_ready or not self.aapl_rsi.is_ready:
            return False
        if self.prev_spy_sma is None:
            return False
        if self.prev_close["SPY"] is None or self.prev_close["AAPL"] is None:
            return False
        return True

    # ------------------------------------------------------------------ #
    # main loop
    # ------------------------------------------------------------------ #
    def on_data(self, data):
        bars = self._collect_bars(data)
        all_present = len(bars) == len(self.TICKERS)

        # ---- today's market-state values (always computed from data) ----
        today_close = {ticker: bar.close for ticker, bar in bars.items()}

        aapl_streak_today = self.aapl_red_streak
        if "AAPL" in bars:
            prev_aapl = self.prev_close["AAPL"]
            close_aapl = today_close["AAPL"]
            if prev_aapl is not None and close_aapl < prev_aapl:
                aapl_streak_today = self.aapl_red_streak + 1
            else:
                aapl_streak_today = 0

        spy_sma_today = self.spy_sma.current.value if self.spy_sma.is_ready else None
        rsi_today = self.aapl_rsi.current.value if self.aapl_rsi.is_ready else None

        # ---- rule evaluation (skipped entirely if any bar is missing) ----
        if all_present and self._ready_to_trade():
            self._evaluate(today_close, spy_sma_today, rsi_today, aapl_streak_today)

        # ---- commit today's values as tomorrow's "previous" values ----
        for ticker, close in today_close.items():
            self.prev_close[ticker] = close
        if "AAPL" in bars:
            self.aapl_red_streak = aapl_streak_today
        if spy_sma_today is not None and "SPY" in bars:
            self.prev_spy_sma = spy_sma_today

    def _evaluate(self, today_close, spy_sma_today, rsi_today, aapl_streak_today):
        spy_close = today_close["SPY"]
        aapl_close = today_close["AAPL"]
        prev_spy_close = self.prev_close["SPY"]

        # =================== SELLS FIRST ===================
        # Slot 1 - Strategy A: SPY close crosses below its moving average.
        if self.lot_a.is_open:
            if self._crosses_below(prev_spy_close, self.prev_spy_sma, spy_close, spy_sma_today):
                self.lot_a.liquidate()

        # Slot 2 - Strategy B: AAPL 14-day RSI closes above 60.
        if self.lot_b.is_open:
            if rsi_today is not None and rsi_today > self.RSI_SELL_LEVEL:
                self.lot_b.liquidate()

        # =================== THEN BUYS =====================
        # Slot 1 - Strategy A: SPY close crosses above its moving average.
        if self.lot_a.is_empty:
            if self._crosses_above(prev_spy_close, self.prev_spy_sma, spy_close, spy_sma_today):
                target_value = self.A_ALLOCATION * self.portfolio.total_portfolio_value
                quantity = int(math.floor(target_value / spy_close))
                if quantity > 0:
                    self.lot_a.buy(quantity)

        # Slot 2 - Strategy B: AAPL red for 3 consecutive days.
        if self.lot_b.is_empty:
            if aapl_streak_today >= self.RED_DAYS_REQUIRED:
                available_cash = self.portfolio.cash
                if available_cash >= self.B_CASH_PER_TRADE:
                    quantity = int(math.floor(self.B_CASH_PER_TRADE / aapl_close))
                    if quantity > 0:
                        self.lot_b.buy(quantity)
                # otherwise: do nothing this bar, stay flat

